mapper.select:
SELECT T1.ENTRUST_ID entrustId, T1.ENTRUST_STATUS entrustStatus, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T3.ASSET_TYPE1 assetType1, T3.BUSI_PS ps, T3.TERM_DAYS termDays, T1.PRICE*100 price, T1.CCY ccy, T1.VDATE vdate, T1.MDATE mdate, T1.ENTRUST_AMT entrustAmt,
T1.INV_MANAGER_ID invManagerId,
IFNULL(T4.FINISH_AMT,0) finishAmt, round(IFNULL(T4.FINISH_AMT,0)/T1.ENTRUST_AMT,4)*100 transactioncom, T1.REMARK remark FROM ETR_ENTRUST T1 inner join PTL_PORTFOLIO T2 on T2.PORTFOLIO_ID = T1.PORTFOLIO_ID inner join ETR_ENTRUST_ADD T3 on T3.ENTRUST_ID = T1.ENTRUST_ID left join (SELECT ENTRUST_ID ,SUM(FINISH_AMT) FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T4 on T4.ENTRUST_ID=T1.ENTRUST_ID inner join PTL_PORTFOLIO_AUTHORITY T5 on T2.PORTFOLIO_ID=T5.PORTFOLIO_ID and T5.USER_ID= #{loginUser}
AND (T2.PORTFOLIO_ID IN
null) OR T2.PORTFOLIO_ID IN (
#{prot}
or T2.PARENT_PORTFOLIO_ID IN
null) OR T2.PARENT_PORTFOLIO_ID IN (
#{prot}
)
AND T3.ASSET_TYPE1 in
#{item}
AND T1.CCY in
#{item}
AND (T3.BUSI_PS in
null) or T3.BUSI_PS in (
#{item} )
AND T1.ENTRUST_STATUS in
#{item}
AND T1.VDATE >= STR_TO_DATE(#{startDate},'%Y-%m-%d')
AND T1.MDATE <=STR_TO_DATE(#{endDate},'%Y-%m-%d')
AND T1.FINPROD_TYPE2 in(#{lendin},#{lendout})
ORDER BY T1.ENTRUST_ID DESC
